{
  "meta": {
    "title": "Start a Trip — Wander.",
    "description": "Create a trip, set your preferences, and start planning together with Wander."
  },
  "onboarding": {
    "eyebrow": "onboarding",
    "skip": "Skip for now",
    "stepOne": {
      "heading": "Let's plan something.",
      "description": "Give your trip a name, then pick what kind of trip it is — we'll show only the tools you actually need.",
      "tripNameLabel": "Trip name",
      "defaultTripName": "Lisbon Long Weekend",
      "tripTypeLabel": "What kind of trip?",
      "types": [
        {
          "id": "day",
          "title": "Day trip",
          "description": "Activities, food, and local transport"
        },
        {
          "id": "local",
          "title": "Local trip",
          "description": "Lodging, activities, food, and ground transport"
        },
        {
          "id": "overseas",
          "title": "Overseas",
          "description": "Flights, lodging, visas, activities, and budgeting"
        }
      ],
      "continue": "Create trip and invite friends",
      "hint": "You can change the trip type later from settings."
    },
    "stepTwo": {
      "heading": "Anything we should account for?",
      "description": "This personalizes the safety and accessibility tags you'll see on locations. You can change this anytime.",
      "options": [
        {
          "id": "accessibility",
          "label": "I’d like accessibility info highlighted (mobility, wheelchair access)"
        },
        {
          "id": "safety",
          "label": "I’d like safety info for solo/women travelers highlighted"
        },
        {
          "id": "dietary",
          "label": "I have dietary restrictions"
        }
      ],
      "dietaryPlaceholder": "e.g., vegetarian, gluten-free...",
      "privacy": "This info is only used to personalize your recommendations — it's never shared with other trip members.",
      "back": "Back",
      "continue": "Continue"
    },
    "stepThree": {
      "heading": "What should we notify you about?",
      "description": "Choose the updates that help you keep the trip moving. You can change these anytime.",
      "options": [
        {
          "id": "poll",
          "label": "New vote or poll created"
        },
        {
          "id": "location",
          "label": "Someone adds a location or item"
        },
        {
          "id": "member",
          "label": "Someone joins or leaves a trip"
        },
        {
          "id": "closing",
          "label": "Poll is about to close"
        },
        {
          "id": "ai",
          "label": "AI route/budget suggestions"
        }
      ],
      "back": "Back",
      "finish": "Finish setup"
    }
  },
  "whiteboard": {
    "nav": {
      "tripCreation": "Trip Creation",
      "whiteboard": "Whiteboard",
      "itinerary": "Itinerary",
      "status": "planning together"
    },
    "toolbar": {
      "addWidget": "Widget",
      "map": "Map",
      "vote": "Vote",
      "viewItinerary": "View itinerary",
      "share": "Share"
    },
    "tip": "✥ Drag widgets anywhere · nothing here is a required step",
    "itinerary": {
      "eyebrow": "Itinerary",
      "days": [
        {
          "id": "day-1",
          "title": "Day 1 · Arrival",
          "description": "Check in, sunset walk, dinner in Alfama"
        },
        {
          "id": "day-2",
          "title": "Day 2 · Belém & Alfama",
          "description": "Belém Tower, MAAT Museum, riverside dinner"
        },
        {
          "id": "day-3",
          "title": "Day 3 · Free day",
          "description": "Add your own plans"
        }
      ]
    }
  }
}
